package limiter

import (
	"testing"
	"time"
)

// Requests that are still inside the window must keep counting after older ones expire.
func TestSlidingWindowLogKeepsUnexpiredRequests(t *testing.T) {
	l := NewSlidingWindowLog(300*time.Millisecond, 3)

	// Two requests at t=0.
	if !l.Allow() || !l.Allow() {
		t.Fatal("the first two requests must be allowed")
	}
	time.Sleep(180 * time.Millisecond)

	// Third request at t~180ms fills the limit of 3.
	if !l.Allow() {
		t.Fatal("the third request must be allowed")
	}
	if l.Allow() {
		t.Fatal("a fourth request inside the window must be rejected")
	}
	time.Sleep(180 * time.Millisecond)

	// t~360ms: the two t=0 requests have expired; the t~180ms request is still inside the window,
	// so exactly two more requests fit.
	if !l.Allow() || !l.Allow() {
		t.Fatal("two requests must be allowed once the two oldest have expired")
	}
	if l.Allow() {
		t.Fatal("the window still holds the t~180ms request, so a third new request must be rejected")
	}
}

func TestSlidingWindowLogRejectsOverLimitAndRecovers(t *testing.T) {
	l := NewSlidingWindowLog(200*time.Millisecond, 2)
	if !l.Allow() || !l.Allow() {
		t.Fatal("the first two requests must be allowed")
	}
	if l.Allow() {
		t.Fatal("the third request inside the window must be rejected")
	}
	time.Sleep(250 * time.Millisecond)
	if !l.Allow() {
		t.Fatal("a request after the whole window has expired must be allowed")
	}
}
